void selection_sort(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int min = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j] < a[min])
                min = j;           /* remember the index, not the value */
        }
        if (min != i) {
            int t = a[i];
            a[i] = a[min];
            a[min] = t;
        }
    }
}

void selection_sort_stable(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int min = i;
        for (int j = i + 1; j < n; j++)
            if (a[j] < a[min]) min = j;     /* first minimum wins */
        int v = a[min];
        for (int k = min; k > i; k--)       /* shift right by one */
            a[k] = a[k - 1];
        a[i] = v;
    }
}

void selection_sort_2way(int a[], int n) {
    for (int lo = 0, hi = n - 1; lo < hi; lo++, hi--) {
        int mn = lo, mx = lo;
        for (int j = lo; j <= hi; j++) {
            if (a[j] < a[mn]) mn = j;
            if (a[j] > a[mx]) mx = j;
        }
        int t = a[lo]; a[lo] = a[mn]; a[mn] = t;
        if (mx == lo) mx = mn;      /* max moved when min swapped in */
        t = a[hi]; a[hi] = a[mx]; a[mx] = t;
    }
}
